import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:resq/services/eligibility_service.dart';

// Second validation set, generated by the backend
// (WEB ADMIN/server/validation/buildValidationSet2.js). Each profile has
// the server classifier's result recorded; the app's classifier must give
// the same one, so the app and the server agree. The recorded result is
// ResQ's output, not the medical technologist's label.
void main() {
  final fixture = jsonDecode(File('test/fixtures/validation_set2.json').readAsStringSync()) as Map<String, dynamic>;
  final profiles = (fixture['profiles'] as List).cast<Map<String, dynamic>>();
  final now = DateTime.now();

  dynamic resolve(dynamic value) {
    if (value is String && value.startsWith('@-')) {
      return now.subtract(Duration(days: int.parse(value.substring(2)))).toIso8601String();
    }
    if (value is List) return value.map(resolve).toList();
    if (value is Map) return value.map((k, v) => MapEntry(k, resolve(v)));
    return value;
  }

  test('validation set 2 has 30 profiles', () => expect(profiles.length, 30));

  for (final p in profiles) {
    test('${p['id']}: ${p['tests']}', () {
      final result = classifyDonorFromProfile({
        'age': p['age'],
        'weightKg': p['weightKg'],
        'gender': p['gender'],
        'lastDonationAt': null,
        'healthScreening': resolve(p['healthScreening']),
      })!;
      final expected = p['resq'] as Map<String, dynamic>;
      expect(result.isEligible ? null : result.status.name, expected['reason']);
      expect(result.daysRemaining > 0 ? result.daysRemaining : null, expected['daysRemaining']);
    });
  }
}
